import sys,statistics as st,random,itertools as it,math
sys.path.insert(0,'.')
import more_itertools as mi
random.seed(3); bad=[]
for t in range(300):
    L=[random.randint(-9,9) for _ in range(random.randint(1,12))]
    if list(mi.running_max(L))!=list(it.accumulate(L,max)): bad.append(('running_max',L,list(mi.running_max(L))))
    if list(mi.running_min(L))!=list(it.accumulate(L,min)): bad.append(('running_min',L,list(mi.running_min(L))))
    rm=list(mi.running_mean(L)); exp=[st.fmean(L[:i+1]) for i in range(len(L))]
    if any(abs(a-b)>1e-9 for a,b in zip(rm,exp)) or len(rm)!=len(L): bad.append(('running_mean',L,rm))
    rmed=list(mi.running_median(L)); exp=[st.median(L[:i+1]) for i in range(len(L))]
    if rmed!=exp: bad.append(('running_median',L,rmed))
    rmw=list(mi.running_median(L,maxlen=3)); exp=[st.median(L[max(0,i-2):i+1]) for i in range(len(L))]
    if rmw!=exp: bad.append(('running_median maxlen',L,rmw))
    d=mi.random_derangement(range(len(L)))
    if len(L)>1 and (sorted(d)!=list(range(len(L))) or any(a==b for a,b in enumerate(d))): bad.append(('random_derangement',len(L),d))
der=[1,0,1,2,9,44,265,1854,14833]
got=[mi.subfactorial(n) for n in range(9)]
if got!=der: bad.append(('subfactorial',got))
s=list(mi.running_statistics([1,2,3,4]))
print('running_statistics last:',s[-1])
z=mi.sized_iterator(iter([1,2,3]),3); print('sized_iterator',len(z),list(z))
for b in bad[:12]: print('FAIL',b)
print('fails',len(bad))
EOF

